import { describe, it, expect } from "vitest";
import { createArcRotateCamera } from "@babylonjs/lite";
import { attachLimitedOrbit } from "./limited-orbit.ts";

type Listener = (e: any) => void;
function fakeCanvas() {
    const map = new Map<string, Set<Listener>>();
    return {
        map,
        addEventListener(t: string, h: Listener) { if (!map.has(t)) map.set(t, new Set()); map.get(t)!.add(h); },
        removeEventListener(t: string, h: Listener) { map.get(t)?.delete(h); },
        setPointerCapture() {}, releasePointerCapture() {},
        fire(t: string, e: any) { for (const h of map.get(t) ?? []) h(e); },
        count() { let n = 0; for (const s of map.values()) n += s.size; return n; },
    };
}
function fakeScene() {
    return { _beforeRender: [] as Array<() => void> } as any;
}

describe("attachLimitedOrbit", () => {
    it("clamps out-of-range start and keeps radius in range under wheel and inertia", () => {
        const cam = createArcRotateCamera(0, 1, 50, { x: 0, y: 0, z: 0 });
        const canvas = fakeCanvas() as any;
        const scene = fakeScene();
        const detach = attachLimitedOrbit(cam, canvas, scene, 2, 10);
        expect(cam.radius).toBe(10);
        for (let i = 0; i < 200; i++) {
            canvas.fire("wheel", { deltaY: i % 2 ? 5000 : -5000, preventDefault() {} });
            for (const f of scene._beforeRender) f();
            expect(cam.radius).toBeGreaterThanOrEqual(2);
            expect(cam.radius).toBeLessThanOrEqual(10);
        }
        // zoom still works
        canvas.fire("wheel", { deltaY: 300, preventDefault() {} });
        for (let i = 0; i < 50; i++) for (const f of scene._beforeRender) f();
        expect(cam.radius).toBeLessThan(10);
        expect(cam.radius).toBeGreaterThanOrEqual(2);
        detach();
        expect(canvas.count()).toBe(0);
        expect(scene._beforeRender.length).toBe(0);
        // limits removed: camera free again
        cam.radius = 100;
        expect(cam.radius).toBe(100);
        detach();
    });
    it("pinch clamps", () => {
        const cam = createArcRotateCamera(0, 1, 5, { x: 0, y: 0, z: 0 });
        const canvas = fakeCanvas() as any;
        const scene = fakeScene();
        const detach = attachLimitedOrbit(cam, canvas, scene, 2, 10);
        const t = (id: number, x: number) => ({ identifier: id, clientX: x, clientY: 0 });
        canvas.fire("touchstart", { changedTouches: [t(1, 0), t(2, 100)], preventDefault() {} });
        canvas.fire("touchmove", { changedTouches: [t(2, 1000)], preventDefault() {} });
        expect(cam.radius).toBe(10);
        canvas.fire("touchmove", { changedTouches: [t(2, 0.5)], preventDefault() {} });
        expect(cam.radius).toBe(2);
        detach();
    });
    it("rejects bad range", () => {
        const cam = createArcRotateCamera(0, 1, 5, { x: 0, y: 0, z: 0 });
        expect(() => attachLimitedOrbit(cam, fakeCanvas() as any, fakeScene(), 10, 2)).toThrow(RangeError);
    });
});
